/* Chapter one: deterministic state transitions, independent of DOM and account transport. */
(function(scope){'use strict';
const D=scope.EverTaleBattleData||(typeof require==='function'?require('./battle-data.js'):null),C=scope.DecideCombatRules||(typeof require==='function'?require('./combat-data.js'):null),copy=x=>JSON.parse(JSON.stringify(x));
const flame={id:'ember-light',name:'ประกายชำระ',cost:12,range:4,power:1.5};
const fresh=()=>({v:1,location:'village',accepted:false,forest:false,learned:false,seal:false,cave:false,ending:'',claimed:false,companion:null,seed:347831,dialog:'elder',route:'',proficiency:0});
function validate(value){if(value===undefined||value===null)return fresh();const w=copy(value);if(w.v!==1||!['village','forest','cave'].includes(w.location)||!['elder','lin','ira',''].includes(w.dialog)||!['','restore','sell'].includes(w.ending)||!['','scout','fight'].includes(w.route)||!Number.isInteger(w.seed)||w.seed<0||w.seed>4294967295||!Number.isInteger(w.proficiency)||w.proficiency<0||w.proficiency>100000)throw Error('ข้อมูลบทผจญภัยไม่ถูกต้อง');for(const k of ['accepted','forest','learned','seal','cave','claimed'])if(typeof w[k]!=='boolean')throw Error('สถานะภารกิจไม่ถูกต้อง');if(w.forest&&!w.accepted||w.learned&&!w.forest||w.seal&&!w.learned||w.cave&&!w.seal||w.ending&&!w.cave||w.claimed&&!w.ending||w.ending&&!w.claimed||w.forest&&!w.route||!w.forest&&w.route||!w.learned&&w.proficiency!==0||w.companion&&!w.accepted)throw Error('ลำดับภารกิจไม่ถูกต้อง');if(w.companion){const u=w.companion;if(u.id!=='lin'||u.name!=='ลิน'||u.job!=='ranger'||!Number.isFinite(u.hp)||u.hp<0||u.hp>100||!Number.isFinite(u.mana)||u.mana<0||u.mana>50)throw Error('ข้อมูลเพื่อนร่วมทางไม่ถูกต้อง');}return w;}
function ready(s){if(!s.character||s.dead||s.event||s.expedition)throw Error('จบเหตุการณ์หรือการต่อสู้ก่อนออกเดินทาง');}
function time(s,n){const t=s.minute+n;s.days+=Math.floor(t/1440);s.minute=t%1440;s.turn++;if(s.ageStart+s.days/365>=s.lifespan)throw Error('เวลาในชีวิตไม่เพียงพอ');}
function change(snapshot,action){ready(snapshot);const s=copy(snapshot),w=s.adventure=validate(s.adventure);const need=(condition,message)=>{if(!condition)throw Error(message);};
 if(action.startsWith('travel:')){const to=action.slice(7);need(['village','forest','cave'].includes(to),'ไม่พบพื้นที่');need(to==='village'||w.accepted,'คุยกับนาราที่หมู่บ้านก่อน');need(to!=='cave'||w.forest,'ยังไม่พบทางเข้าถ้ำ');if(to!==w.location){need(s.energy>=5,'พลังงานไม่พอ เดินทางใช้ 5');s.energy-=5;time(s,30);w.location=to;}w.dialog='';}
 else if(action.startsWith('talk:')){need(w.location==='village','NPC อยู่ที่หมู่บ้าน');const id=action.slice(5);need(['elder','lin','ira'].includes(id),'ไม่พบผู้สนทนา');w.dialog=id;}
 else if(action==='accept'){need(w.location==='village'&&!w.accepted,'รับงานนี้แล้ว');w.accepted=true;}
 else if(action==='recruit'){need(w.location==='village'&&w.accepted&&!w.companion,'ยังรับเพื่อนร่วมทางไม่ได้');w.companion={id:'lin',name:'ลิน',job:'ranger',hp:100,mana:50};}
 else if(action==='scout'){need(w.location==='forest'&&!w.forest&&w.accepted,'สำรวจเส้นทางนี้แล้ว');need(s.energy>=10,'ต้องมีพลังงาน 10');s.energy-=10;time(s,60);w.forest=true;w.route='scout';s.proficiency.Survival=(s.proficiency.Survival||0)+8;}
 else if(action==='learn'){need(w.location==='forest'&&w.forest&&!w.learned,'ต้องพบศาลาก่อน');w.learned=true;w.proficiency=1;s.known['spell:ember-light']=2;if(!s.learned.includes('spell:ember-light'))s.learned.push('spell:ember-light');s.proficiency['Ember Light']=1;}
 else if(action==='seal'){need(w.location==='cave'&&w.learned&&!w.seal,'ต้องเรียนประกายชำระก่อน');need(s.mp>=flame.cost,'มานาไม่พอ (12)');s.mp-=flame.cost;w.seal=true;w.proficiency++;s.proficiency['Ember Light']=w.proficiency;}
 else if(action==='rest'){need(w.location==='village','พักได้ที่หมู่บ้าน');time(s,480);s.hp=s.character?.design===1?60+4*s.character.stats.CON:100;s.energy=100;s.mp=s.maxMp;if(s.character?.design===1)s.character.inventory.reagents=3;if(w.companion){w.companion.hp=100;w.companion.mana=50;}}
 else if(['restore','sell'].includes(action)){need(w.location==='village'&&w.cave&&!w.claimed,'ยังรับผลภารกิจไม่ได้ หรือรับไปแล้ว');w.ending=action;w.claimed=true;s.gold+=action==='restore'?60:100;s.earned+=action==='restore'?60:100;}
 else throw Error('การกระทำไม่ถูกต้อง');return s;
}
function battle(snapshot,kind){ready(snapshot);const s=copy(snapshot),w=s.adventure=validate(s.adventure);if(!['forest','cave'].includes(kind)||w.location!==kind||!w.accepted||kind==='forest'&&w.forest||kind==='cave'&&(!w.seal||w.cave))throw Error('ยังเข้าสู่การต่อสู้นี้ไม่ได้');
 const scene=D.generate('chapter-'+kind,kind,12,10,'CHAPTER-1-'+kind,'ruins');scene.name=kind==='forest'?'ทางสู่ศาลาป่ากระซิบ':'ห้องหัวใจธาร';for(const c of scene.cells){c.spawn='';c.monster='';}for(let y=3;y<=6;y++)for(let x=1;x<=9;x++)scene.cells[y*12+x]={...D.tile(),terrain:'path'};scene.cells[4*12+2].spawn='player';scene.cells[4*12+7].spawn='enemy';
 const roll=()=>{let x=w.seed;x^=x<<13;x^=x>>>17;x^=x<<5;w.seed=x>>>0;return w.seed/4294967296;};
 const companion=w.companion?.hp>0?w.companion:null;const e=C.create(scene,s,[{id:'chapter-warden',name:kind==='forest'?'ผู้เฝ้ารากไม้':'ผู้พิทักษ์ผลึก',hp:kind==='forest'?24:42,str:8,level:1}], 'chapter-'+kind+'-'+s.turn,roll,{tactical:true,partyJobs:companion?['ranger']:[],enemyCount:kind==='forest'?1:2});
 e.chapter=kind;e.chapterSpell=w.learned?flame.id:'';e.spellUses=0;e.chapterPower=flame.power+Math.min(.5,w.proficiency*.02);if(companion){const u=e.units.find(u=>u.id==='ally-0');u.name=companion.name;u.hp=companion.hp;u.mana=companion.mana;}s.energy-=15;time(s,120);s.expedition=e;return s;
}
function settle(s,e){const w=s.adventure=validate(s.adventure);if(!e.chapter)return s;const ally=e.units.find(u=>u.id==='ally-0');if(w.companion&&ally){w.companion.hp=ally.hp;w.companion.mana=ally.mana;}w.proficiency+=e.spellUses||0;if(w.learned)s.proficiency['Ember Light']=w.proficiency;if(e.status==='won'){if(e.chapter==='forest'){w.forest=true;w.route='fight';}else w.cave=true;}return s;}
const api={fresh,validate,change,battle,settle,flame};scope.DecideAdventure=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
